String postfixToPrefix(String s) {
    List<String> text = new ArrayList<>();       // each item's text
    List<Boolean> isOp = new ArrayList<>();      // and whether it's a bare operator
    for (char c : s.toCharArray()) {
        text.add(String.valueOf(c));
        isOp.add("+-*/^".indexOf(c) >= 0);
    }
    while (text.size() > 1) {
        for (int i = 0; i + 2 < text.size(); i++) {
            // two finished operands followed by an operator are an innermost operation
            if (!isOp.get(i) && !isOp.get(i + 1) && isOp.get(i + 2)) {
                String piece = text.get(i + 2) + text.get(i) + text.get(i + 1);
                text.subList(i, i + 3).clear();
                isOp.subList(i, i + 3).clear();
                text.add(i, piece);
                isOp.add(i, false);              // the piece is an operand now
                break;                           // the list changed: start over
            }
        }
    }
    return text.get(0);
}

