    vector<pair<string, bool>> items;          // (text, is it a bare operator?)
    for (char c : s) items.push_back({string(1, c), string("+-*/^").find(c) != string::npos});
    while (items.size() > 1) {
        for (size_t i = 0; i + 2 < items.size(); i++) {
            // two finished operands followed by an operator are an innermost operation
            if (!items[i].second && !items[i + 1].second && items[i + 2].second) {
                string piece = items[i + 2].first + items[i].first + items[i + 1].first;
                items.erase(items.begin() + i, items.begin() + i + 3);
