function postfixToPrefix(s) {
  let i = s.length - 1;                      // read from the end
  function build() {
    const c = s[i--];
    if (!"+-*/^".includes(c)) return c;      // an operand is complete on its own
    const right = build();                   // reading backwards, the right operand comes first
    const left = build();
    return c + left + right;                 // the operator goes first
  }
  return build();
}

