private String build(String s) {
    char c = s.charAt(i--);
    if ("+-*/^".indexOf(c) < 0) return String.valueOf(c);   // an operand is complete on its own
    String right = build(s);                 // reading backwards, the right operand comes first
    String left = build(s);
    return c + left + right;                 // the operator goes first
}

string build(const string& s, int& i) {
    char c = s[i--];
    if (string("+-*/^").find(c) == string::npos) return string(1, c);   // an operand is complete on its own
    string right = build(s, i);              // reading backwards, the right operand comes first
    string left = build(s, i);
    return c + left + right;                 // the operator goes first
}

string postfixToPrefix(const string& s) {
    int i = (int)s.size() - 1;               // read from the end
    return build(s, i);
}

function postfixToPrefix(s) {
  const stack = [];
  for (const c of s) {                           // read left to right
    if ("+-*/^".includes(c)) {
      const right = stack.pop();                 // the right operand is on top
      const left = stack.pop();
      stack.push(c + left + right);              // the operator goes first
    } else {
      stack.push(c);                             // an operand
    }
  }
  return stack.pop();
}

