    Deque<String> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {             // read left to right
        if ("+-*/^".indexOf(c) >= 0) {
            String right = stack.pop();          // the right operand is on top
            String left = stack.pop();
            stack.push(c + left + right);        // the operator goes first
