string postfixToPrefix(const string& s) {
    stack<string> st;
    for (char c : s) {                           // read left to right
        if (string("+-*/^").find(c) != string::npos) {
            string right = st.top(); st.pop();   // the right operand is on top
            string left = st.top(); st.pop();
            st.push(c + left + right);           // the operator goes first
        } else {
            st.push(string(1, c));               // an operand
        }
    }
    return st.top();
}
